    '1HdglQ2VZ1qYdieTA8e2pGIxmL54MqPrU',
    '19DSBRkRrjcA-XIx_cFgzSv0oSEvP3AKx'
  ],
  'Chair': [
    '1qWfFKxd6HCpOio5DqEnURT8hBsE_CZMU',
    '1BTJ7G91L05LbrzQI5OfeXWqt_fY1kg1R',
    '1CVmiRauex3ZILPcevQeGVU3b_svH_b6_'
  ],
  'Barrel': [
    '1ye7RmXboj41tt3-io08yqpKvn5iYVbb2',
    '1zJs3TywJVXm9u1S08TueH9ymAc8mWjwx',
    '1wDvHZsglZFhMW_iMrjMl7Dp8Yo6Sssy5'
  ]
};

const imageIds = productImages[productName] || productImages['Chair'];

return imageIds.map((imageId, index) => ({
  json: {
    recipient: recipient,
    mediaUrl: `https://drive.google.com/uc?export=download&id=${imageId}`,
    caption: index === 0 ? productName : '',
    isLast: index === imageIds.length - 1
  }
}));

